steps.code:
existing_ratings = {}
for song in liked_songs:
    reviews = []
    page_index = 0
    while True:
        page = apis.spotify.show_song_reviews(song_id=song['song_id'], user_email='as_moore@gmail.com', page_index=page_index, page_limit=20)
        if not page:
            break
        reviews.extend(page)
        page_index += 1
    if reviews:
        existing_ratings[song['song_id']] = reviews[0]['rating']

rating_summary = {
    'already_five': sum(1 for rating in existing_ratings.values() if rating == 5.0),
    'lower_than_five': sum(1 for rating in existing_ratings.values() if rating < 5.0),
    'missing': len(liked_songs) - len(existing_ratings)
}
print(rating_summary)

