leslie_message_threads = []
for contact in leslie_contacts:
    if contact['first_name'] == 'Leslie':
        messages = []
        page_index = 0
        while True:
            page = apis.phone.search_text_messages(access_token=phone_access_token, phone_number=contact['phone_number'], only_latest_per_contact=True, page_index=page_index, page_limit=20)
            if not page:
                break
            messages.extend(page)
            page_index += 1
        leslie_message_threads.append({'contact': contact, 'messages': messages})
print(leslie_message_threads)

